alter table public.organizations add column if not exists primary_contact_phone text;
alter table public.businesses add column if not exists description text;
alter table public.integration_connections add column if not exists instructions text;
alter table public.integration_connections add column if not exists private_metadata jsonb not null default '{}';
create table if not exists public.access_request_templates(id uuid primary key default gen_random_uuid(),title text not null,integration_id uuid references public.integrations(id) on delete set null,instructions text not null,active boolean not null default true,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.client_access_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,template_id uuid references public.access_request_templates(id) on delete set null,title text not null,instructions text not null,status text not null default 'requested' check(status in ('requested','viewed','submitted','completed','cancelled')),response_notes text,requested_by uuid not null references public.profiles(id),sent_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_client_access_requests_org on public.client_access_requests(organization_id,status,created_at desc);
alter table public.access_request_templates enable row level security;alter table public.client_access_requests enable row level security;
create policy "access templates staff only" on public.access_request_templates for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "access requests scoped read" on public.client_access_requests for select to authenticated using(public.has_organization_access(organization_id));
create policy "access requests staff write" on public.client_access_requests for all to authenticated using(public.is_staff()) with check(public.is_staff());
grant select,insert,update,delete on public.access_request_templates to authenticated;grant select,insert,update on public.client_access_requests to authenticated;
create or replace function public.update_client_workspace_profile(target_business uuid,contact_name text,contact_email text,contact_phone text,business_name text,business_industry text,business_website text,business_description text) returns void language plpgsql security definer set search_path=public as $$ declare target_org uuid;begin select organization_id into target_org from public.businesses where id=target_business;if target_org is null or not public.has_organization_access(target_org) then raise exception 'forbidden';end if;update public.organizations set primary_contact_name=left(contact_name,160),primary_contact_email=left(contact_email,320),primary_contact_phone=left(contact_phone,40) where id=target_org;update public.businesses set name=left(business_name,180),industry=left(business_industry,160),website=left(business_website,500),description=left(business_description,3000) where id=target_business;update public.profiles set full_name=left(contact_name,160),email=left(contact_email,320) where id=auth.uid();end $$;
revoke all on function public.update_client_workspace_profile(uuid,text,text,text,text,text,text,text) from public;grant execute on function public.update_client_workspace_profile(uuid,text,text,text,text,text,text,text) to authenticated;
create or replace function public.respond_to_access_request(target_request uuid,new_status text,response text) returns void language plpgsql security definer set search_path=public as $$ declare target_org uuid;begin if new_status not in ('viewed','submitted') then raise exception 'invalid status';end if;select organization_id into target_org from public.client_access_requests where id=target_request;if target_org is null or not public.has_organization_access(target_org) then raise exception 'forbidden';end if;update public.client_access_requests set status=new_status,response_notes=left(response,3000) where id=target_request;end $$;
revoke all on function public.respond_to_access_request(uuid,text,text) from public;grant execute on function public.respond_to_access_request(uuid,text,text) to authenticated;
